+import { PgContactRepository } from "../infrastructure/pg-contact.repository";
+
+export interface Contact {
+  readonly id: string;
+  readonly organisationId: string;
+  readonly name: string;
+  readonly phone: string;
+}
+
+export function greetingFor(contact: Contact, organisationName: string): string {
+  if (organisationName === "Gurlitt") {
